def build():
    out = Path(__file__).resolve().parent.parent / "klipo_app" / "web" / "i18n"
    out.mkdir(parents=True, exist_ok=True)
    for k, lang in ((1, "en"), (2, "ru")):
        tam, kalip = {}, []
        for row in D:
            src, dst = row[0], row[k]
            if "{0}" in src:
                kalip.append([src, dst])
            else:
                tam[src] = dst
        # uzun kalıplar önce denensin
        kalip.sort(key=lambda r: -len(r[0]))
        (out / f"{lang}.json").write_text(json.dumps({"tam": tam, "kalip": kalip}, ensure_ascii=False, indent=0), encoding="utf-8")
        print(lang, len(tam), "metin,", len(kalip), "kalıp")


if __name__ == "__main__":
    build()
